a=p.parse_args();root=a.workspace_root.resolve();root.mkdir(exist_ok=False);fixture=a.fixture_root.resolve();job=a.drc_root.resolve();f=json.loads((fixture/'report.json').read_text(encoding='utf-8'));r=json.loads((job/'report.json').read_text(encoding='utf-8'));log=(job/'native-report.log').read_text(encoding='utf-8');source=fixture/'MCP_DRC_ERROR.dsn';expected={(ref,pin) for ref,pin in [('R1','2'),('R_load','2'),('R_Load1','2'),('C1','1')]};old={(v['reference'],v['number']):v['type'] for v in f['write']['before']};new={(v['reference'],v['number']):v['type'] for v in f['read']['after']};changed={k for k in old if old[k]!=new[k]};counts={v['severity']:v['count'] for v in r['receipt']['countsAfter']};checks={'fixtureSavedReopened':f['passed'] and len(old)==len(new)==14 and changed==expected and all(new[k]==2 for k in expected),'acknowledged':r['acknowledged'] and r['receipt']['invocationReturned'],'sourceIdentity':r['sourceUnchanged'] and sha256(source)==r['sourceSha256'],'freshReport':not r['priorNativeLog']['exists'] and r['nativeLog']['fresh'] and sha256(job/'native-report.log')==r['nativeLog']['sha256'],'reportDesignIdentity':str(source).upper() in log.upper(),'expectedElectricalErrorDetected':counts.get('DRC_ERROR',0)>0};report={'passed':all(checks.values()),'checks':checks,'counts':counts,'expectedConflict':'Two output pins on N00509 plus two outputs on ground; no oracle weakening.','conclusion':'Online DRC returned zero despite saved intentional conflict; rule coverage/configuration unproven. This is not clean electrical acceptance.','inputSha256':{str(path):sha256(path) for path in (fixture/'report.json',job/'report.json',job/'native-report.log')}};(root/'report.json').write_text(json.dumps(report,indent=2),encoding='utf-8');print(json.dumps(report),flush=True)
